                r += 1
                continue
            start = r
            while r < h and grid[r][c] != background:
                r += 1
            end = r - 1
            length = end - start + 1
            if length >= 2 and start >= h // 2:
                right_count = sum(
                    grid[rr][c + 1] != background
                    for rr in range(start, end + 1)
                )
                runs.append((length, right_count, -c, start, c, end))

    mappings = []
    key_cells = set()
