def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(
        (v for row in grid for v in row),
        key=lambda v: sum(row.count(v) for row in grid)
    )

    # The key is a vertical two-column table in the lower part of the grid.
    candidates = []
    for c in range(w - 1):
        r = h // 2
        while r < h:
            if grid[r][c] == background:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] != background:
                r += 1
            end = r - 1
            if end - start + 1 >= 2:
                count = sum(
                    grid[rr][cc] != background
                    for rr in range(start, end + 1)
                    for cc in (c, c + 1)
                )
                candidates.append((end - start + 1, count, -c, start, end, c))

    if candidates:
        _, _, _, key_start, key_end, key_col = max(candidates)
        key_cells = {
            (r, c)
            for r in range(key_start, key_end + 1)
            for c in (key_col, key_col + 1)
        }
        mappings = [
            (grid[r][key_col], grid[r][key_col + 1])
            for r in range(key_start, key_end + 1)
        ]
    else:
        key_cells = set()
        mappings = []

    # Find connected same-color objects, excluding the key.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in key_cells or (r, c) in seen:
                continue
            color = grid[r][c]
            if color == background:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                rr, cc = stack.pop()
                cells.add((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (
                        0 <= nr < h and 0 <= nc < w
                        and (nr, nc) not in key_cells
                        and (nr, nc) not in seen
                        and grid[nr][nc] == color
                    ):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append((color, cells))

    l_shapes = {}
    squares = {}
    for color, cells in components:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)

        if len(cells) == 3 and r1 - r0 == 1 and c1 - c0 == 1:
            l_shapes.setdefault(color, []).append(cells)
        elif len(cells) == 4 and r1 - r0 == 1 and c1 - c0 == 1:
            squares.setdefault(color, []).append(cells)

    out = [row[:] for row in grid]

    # Apply table entries from bottom to top. A target of zero clears to
    # the original background color.
    for source, target in reversed(mappings):
        fill = background if target == 0 else target

        shapes = l_shapes.get(source, [])
        if len(shapes) == 2:
            cells = shapes[0] | shapes[1]
            r0 = min(r for r, c in cells)
            r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells)
            c1 = max(c for r, c in cells)

            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = source if grid[r][c] == source else fill

        for cells in squares.get(source, []):
            for r, c in cells:
                out[r][c] = fill

    return out
